function tableKey(t){return String(t?.regId||state.viewer.regulation||state.regulation)+':'+String(nid(t)||'table')}
function tableColumnCount(t){const cols=Array.isArray(t.columns)?t.columns:[];const rows=Array.isArray(t.rows)?t.rows:[];const rowWidth=Math.max(0,...rows.map(row=>(Array.isArray(row)?row:[]).reduce((sum,cell)=>sum+Math.max(1,Number((cell&&typeof cell==='object'?cell.colspan:1)||1)),0)));return Math.max(cols.length,rowWidth)}
function tableColgroup(t){const cols=Array.isArray(t.columns)?t.columns:[],count=tableColumnCount(t);if(!count)return'';const stars=cols.map(c=>{const m=String(c?.colwidth||'').match(/^([0-9.]+)\*$/);return m?Number(m[1]):0}),sum=stars.reduce((a,b)=>a+b,0);return `<colgroup>${Array.from({length:count},(_,i)=>{const c=cols[i]||{},w=sum&&stars[i]?` style="width:${(stars[i]/sum*100).toFixed(4)}%"`:/^\d+(?:\.\d+)?(?:mm|cm|px|pt|%)$/.test(String(c.colwidth||''))?` style="width:${esc(c.colwidth)}"`:'';return `<col data-table-column="${i}"${w}>`}).join('')}</colgroup>`}
function tableCellClass(o){const a=String(o?.attrs?.align||'').toLowerCase(),v=String(o?.attrs?.valign||'').toLowerCase();return `${['left','right','center','justify'].includes(a)?' tableAlign-'+a:''}${['top','middle','bottom'].includes(v)?' tableValign-'+v:''}`}
function renderTable(t){const rows=Array.isArray(t.rows)?t.rows:[];if(!rows.length)return `<div class="legalText">${renderInline(t,ownText(t))}</div>`;const key=tableKey(t);return `<div class="tableWrap"><table class="legalTable" data-resizable-table data-table-key="${esc(key)}">${tableColgroup(t)}<tbody>${rows.map((r,ri)=>`<tr>${(Array.isArray(r)?r:[]).map((c,ci)=>{const o=typeof c==='object'&&c?c:{text:c};const rs=Number(o.rowspan||1),cs=Number(o.colspan||1),tag=o.header?'th':'td',cl=tableCellClass(o),handle=ri===0&&ci+cs<tableColumnCount(t)?`<span class="tableResizeHandle" data-table-resize="${ci}" title="Sleep om de kolombreedte aan te passen" aria-hidden="true"></span>`:'';return `<${tag}${rs>1?` rowspan="${rs}"`:''}${cs>1?` colspan="${cs}"`:''}${cl?` class="${cl.trim()}"`:''}>${renderInline(t,o.text??'')}${handle}</${tag}>`}).join('')}</tr>`).join('')}</tbody></table></div>`}
function bindTableResizers(root){root.querySelectorAll('table[data-resizable-table]').forEach(table=>{const cols=[...table.querySelectorAll('colgroup col')];if(cols.length<2)return;const key=table.dataset.tableKey||'';try{const saved=JSON.parse(localStorage.getItem('owz_table_widths:'+key)||'null');if(Array.isArray(saved)&&saved.length===cols.length)saved.forEach((w,i)=>cols[i].style.width=Math.max(70,Number(w)||70)+'px')}catch(_){}table.querySelectorAll('.tableResizeHandle').forEach(handle=>handle.addEventListener('mousedown',event=>{event.preventDefault();event.stopPropagation();const i=Number(handle.dataset.tableResize),next=cols[i+1];if(!cols[i]||!next)return;const widths=cols.map(col=>col.getBoundingClientRect().width);const start=event.clientX,left=widths[i],right=widths[i+1],total=widths.reduce((sum,w)=>sum+w,0);table.style.width=total+'px';document.body.classList.add('resizing');const move=e=>{const delta=e.clientX-start,a=Math.max(70,left+delta),b=Math.max(70,right-delta);if(a+b!==left+right)return;cols[i].style.width=a+'px';next.style.width=b+'px'};const up=()=>{document.removeEventListener('mousemove',move);document.removeEventListener('mouseup',up);document.body.classList.remove('resizing');try{localStorage.setItem('owz_table_widths:'+key,JSON.stringify(cols.map(col=>Math.round(col.getBoundingClientRect().width))))}catch(_){}};document.addEventListener('mousemove',move);document.addEventListener('mouseup',up)}))})}
