const REF_RE=/\b(artikel|art\.?|paragraaf|afdeling|hoofdstuk|tabel|table|bijlage)\s+([0-9]+(?:\.[0-9]+)*[a-z]?|[IVXLCDM]+(?:[a-z]+)?)|§\s*([0-9]+(?:\.[0-9]+)*[a-z]?)/gi;
const REGULATION_ALIASES=[
 {reg:'OW',re:/\b(?:de\s+)?Omgevingswet\b/i},
 {reg:'BAL',re:/\b(?:het\s+)?Besluit\s+activiteiten\s+leefomgeving(?:\s*\(BAL\))?|\bBAL\b/i},
 {reg:'BBL',re:/\b(?:het\s+)?Besluit\s+bouwwerken\s+leefomgeving(?:\s*\(BBL\))?|\bBBL\b/i},
 {reg:'BKL',re:/\b(?:het\s+)?Besluit\s+kwaliteit\s+leefomgeving(?:\s*\(BKL\))?|\bBKL\b/i},
 {reg:'OB',re:/\b(?:het\s+)?Omgevingsbesluit(?:\s*\(OB\))?|\bOB\b/i},
 {reg:'OR',re:/\b(?:de\s+)?Omgevingsregeling(?:\s*\(OR\))?|\bOR\b/i}
];
const EXTERNAL_REGULATION_RE=/\b((?:Wet|Besluit|Regeling|Verordening|Richtlijn)\s+(?:(?![.;:\n]|\s+(?:en|of)\s+(?:artikel|paragraaf|hoofdstuk|afdeling)\b).){2,100})/gi;
function regulationMention(text){const raw=String(text||'');for(const x of REGULATION_ALIASES){const m=raw.match(x.re);if(m)return{reg:x.reg,name:regName(x.reg),match:m[0]}}return null}
function resolveRef(anchor,reg=state.regulation){const m=String(anchor).match(/^(artikel|art\.?|paragraaf|afdeling|hoofdstuk|tabel|table|bijlage)\s+(.+)$|^§\s*(.+)$/i);if(!m)return null;let k=(m[1]||'paragraaf').toLowerCase().replace('.',''),no=normNum(m[2]||m[3]);k=({artikel:'article',art:'article',paragraaf:'paragraph',afdeling:'section',hoofdstuk:'chapter',tabel:'table',table:'table',bijlage:'appendix'})[k]||k;return index(reg)?.byLegal.get(k+':'+no)||null}
function resolveCrossRegRef(anchor,context){const mention=regulationMention(context);if(!mention)return null;const target=resolveRef(anchor,mention.reg);return{...mention,target}}
